import { spawn } from 'child_process';
import { logger } from '../lib/logger';

// eslint-disable-next-line @typescript-eslint/no-var-requires
const ffmpegInstaller = require('@ffmpeg-installer/ffmpeg');
const ffmpegPath: string = ffmpegInstaller.path || 'ffmpeg';

export class AudioProcessor {
  /**
   * Converts an MP3 buffer (generated by TTS) into raw 8000Hz 8-bit mono μ-law (PCMU)
   * which is the exact format expected by Twilio Media Streams over WebSocket.
   */
  async mp3ToMulaw(mp3Buffer: Buffer): Promise<Buffer> {
    return new Promise<Buffer>((resolve, reject) => {
      const proc = spawn(ffmpegPath, [
        '-probesize', '32',
        '-analyzeduration', '0',
        '-fflags', 'nobuffer',
        '-flags', 'low_delay',
        '-i', 'pipe:0',
        '-f', 'mulaw',
        '-ar', '8000',
        '-ac', '1',
        'pipe:1',
      ]);

      const chunks: Buffer[] = [];
      proc.stdout.on('data', (d: Buffer) => chunks.push(d));
      proc.stderr.on('data', () => { /* suppress debug output */ });

      proc.on('close', (code) => {
        if (code === 0) {
          resolve(Buffer.concat(chunks));
        } else {
          logger.error(`[AudioProcessor] ffmpeg mp3ToMulaw failed with code ${code}`);
          reject(new Error(`ffmpeg exited with code ${code}`));
        }
      });

      proc.on('error', (err) => {
        logger.error(`[AudioProcessor] ffmpeg error: ${err.message}`);
        reject(err);
      });

      proc.stdin.write(mp3Buffer);
      proc.stdin.end();
    });
  }

  /**
   * Converts a raw 8000Hz μ-law buffer into a 16000Hz 16-bit mono PCM WAV buffer
   * using ultra-fast in-memory decoding (0.1ms instead of 1200ms ffmpeg spawn).
   */
  async mulawToWav(mulawBuffer: Buffer): Promise<Buffer> {
    const numInputSamples = mulawBuffer.length;
    const numOutputSamples = numInputSamples * 2; // 8kHz upsampled to 16kHz for Whisper
    const dataSize = numOutputSamples * 2;
    const wavBuffer = Buffer.alloc(44 + dataSize);

    // RIFF Header
    wavBuffer.write('RIFF', 0);
    wavBuffer.writeUInt32LE(36 + dataSize, 4);
    wavBuffer.write('WAVE', 8);
    // fmt chunk
    wavBuffer.write('fmt ', 12);
    wavBuffer.writeUInt32LE(16, 16);
    wavBuffer.writeUInt16LE(1, 20);
    wavBuffer.writeUInt16LE(1, 22);
    wavBuffer.writeUInt32LE(16000, 24);
    wavBuffer.writeUInt32LE(32000, 28);
    wavBuffer.writeUInt16LE(2, 32);
    wavBuffer.writeUInt16LE(16, 34);
    // data chunk
    wavBuffer.write('data', 36);
    wavBuffer.writeUInt32LE(dataSize, 40);

    let offset = 44;
    for (let i = 0; i < numInputSamples; i++) {
      const sample = this.mulawToLinear(mulawBuffer[i]);
      wavBuffer.writeInt16LE(sample, offset);
      wavBuffer.writeInt16LE(sample, offset + 2);
      offset += 4;
    }

    return wavBuffer;
  }

  /**
   * Decodes a single μ-law byte into a 16-bit signed PCM value [-32768, 32767].
   */
  mulawToLinear(byte: number): number {
    const s = ~byte & 0xff;
    const sign = s & 0x80;
    const exponent = (s >> 4) & 0x07;
    const mantissa = s & 0x0f;
    let sample = ((mantissa << 3) + 0x84) << exponent;
    sample -= 0x84;
    return sign ? -sample : sample;
  }

  /**
   * Encodes a 16-bit signed linear PCM sample [-32768, 32767] into a μ-law byte.
   */
  linearToMulaw(pcmSample: number): number {
    const BIAS = 0x84;
    const CLIP = 32635;
    let sign = (pcmSample >> 8) & 0x80;
    if (sign !== 0) pcmSample = -pcmSample;
    if (pcmSample > CLIP) pcmSample = CLIP;
    pcmSample = (pcmSample + BIAS) >> 2;

    let exponent = 7;
    for (let expMask = 0x4000; (pcmSample & expMask) === 0 && exponent > 0; expMask >>= 1) {
      exponent--;
    }
    const mantissa = (pcmSample >> (exponent === 0 ? 0 : exponent - 1)) & 0x0f;
    return ~(sign | (exponent << 4) | mantissa) & 0xff;
  }

  /**
   * Computes the RMS energy of a μ-law audio chunk for Voice Activity Detection (VAD).
   */
  getRms(mulawChunk: Buffer): number {
    if (!mulawChunk || mulawChunk.length === 0) return 0;
    let sum = 0;
    for (let i = 0; i < mulawChunk.length; i++) {
      const sample = this.mulawToLinear(mulawChunk[i]);
      sum += sample * sample;
    }
    return Math.sqrt(sum / mulawChunk.length);
  }

  /**
   * Detects if an incoming μ-law chunk contains speech above a background threshold.
   */
  isSpeech(mulawChunk: Buffer, threshold: number = 400): boolean {
    return this.getRms(mulawChunk) > threshold;
  }

  /**
   * Detects whether a μ-law buffer contains a phone keypad DTMF tone (dual tone).
   * Used for instantly detecting when a caller presses a key to clear Twilio's trial prompt.
   */
  isDtmfTone(mulawBuffer: Buffer): boolean {
    if (!mulawBuffer || mulawBuffer.length < 320) return false;
    const N = mulawBuffer.length;
    const SAMPLING_RATE = 8000;
    const DTMF_LOW = [697, 770, 852, 941];
    const DTMF_HIGH = [1209, 1336, 1477, 1633];

    let totalPower = 0;
    const samples: number[] = new Array(N);
    for (let i = 0; i < N; i++) {
      const s = this.mulawToLinear(mulawBuffer[i]);
      samples[i] = s;
      totalPower += s * s;
    }
    if (totalPower < 100000) return false; // Too low energy to be a keypress tone

    const goertzelPower = (freq: number) => {
      const k = Math.round((N * freq) / SAMPLING_RATE);
      const omega = (2 * Math.PI * k) / N;
      const coeff = 2 * Math.cos(omega);
      let s_prev = 0;
      let s_prev2 = 0;
      for (let i = 0; i < N; i++) {
        const s = samples[i] + coeff * s_prev - s_prev2;
        s_prev2 = s_prev;
        s_prev = s;
      }
      return s_prev * s_prev + s_prev2 * s_prev2 - coeff * s_prev * s_prev2;
    };

    let maxLowPower = 0;
    for (const f of DTMF_LOW) {
      const p = goertzelPower(f);
      if (p > maxLowPower) maxLowPower = p;
    }

    let maxHighPower = 0;
    for (const f of DTMF_HIGH) {
      const p = goertzelPower(f);
      if (p > maxHighPower) maxHighPower = p;
    }

    const dtmfCombined = (maxLowPower + maxHighPower) / (N / 2);
    const ratio = dtmfCombined / totalPower;
    return ratio > 0.30;
  }

  /**
   * Decodes a phone keypad DTMF tone (0-9, *, #) from an incoming μ-law buffer using the Goertzel algorithm.
   * Returns the decoded digit character ('0'-'9', '*', '#') or null if not a valid DTMF tone.
   */
  decodeDtmfDigit(mulawBuffer: Buffer): string | null {
    if (!mulawBuffer || mulawBuffer.length < 160) return null;
    const N = mulawBuffer.length;
    const SAMPLING_RATE = 8000;
    const DTMF_LOW = [697, 770, 852, 941];
    const DTMF_HIGH = [1209, 1336, 1477, 1633];
    const DTMF_MAP: string[][] = [
      ['1', '2', '3', 'A'],
      ['4', '5', '6', 'B'],
      ['7', '8', '9', 'C'],
      ['*', '0', '#', 'D']
    ];

    let totalPower = 0;
    const samples: number[] = new Array(N);
    for (let i = 0; i < N; i++) {
      const s = this.mulawToLinear(mulawBuffer[i]);
      samples[i] = s;
      totalPower += s * s;
    }
    if (totalPower < 60000) return null;

    const goertzelPower = (freq: number) => {
      const k = Math.round((N * freq) / SAMPLING_RATE);
      const omega = (2 * Math.PI * k) / N;
      const coeff = 2 * Math.cos(omega);
      let s_prev = 0;
      let s_prev2 = 0;
      for (let i = 0; i < N; i++) {
        const s = samples[i] + coeff * s_prev - s_prev2;
        s_prev2 = s_prev;
        s_prev = s;
      }
      return s_prev * s_prev + s_prev2 * s_prev2 - coeff * s_prev * s_prev2;
    };

    let bestLowIdx = -1;
    let maxLowPower = 0;
    for (let i = 0; i < DTMF_LOW.length; i++) {
      const p = goertzelPower(DTMF_LOW[i]);
      if (p > maxLowPower) {
        maxLowPower = p;
        bestLowIdx = i;
      }
    }

    let bestHighIdx = -1;
    let maxHighPower = 0;
    for (let j = 0; j < DTMF_HIGH.length; j++) {
      const p = goertzelPower(DTMF_HIGH[j]);
      if (p > maxHighPower) {
        maxHighPower = p;
        bestHighIdx = j;
      }
    }

    if (bestLowIdx === -1 || bestHighIdx === -1) return null;

    const dtmfCombined = (maxLowPower + maxHighPower) / (N / 2);
    const ratio = dtmfCombined / totalPower;
    if (ratio > 0.22) {
      return DTMF_MAP[bestLowIdx][bestHighIdx];
    }
    return null;
  }

  /**
   * Legacy method for backward compatibility
   */
  processForTwilio(pcmBuffer: Buffer): Buffer {
    return pcmBuffer;
  }

  /**
   * Legacy method for backward compatibility
   */
  processForSTT(mulawBase64: string): Buffer {
    return Buffer.from(mulawBase64, 'base64');
  }
}

export const audioProcessor = new AudioProcessor();
